import{_ as e,o as t,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-06","description":"","frontmatter":{"date":"2026-08-06T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-06-uxtrend.md","filePath":"daily/2026-08-06-uxtrend.md"}'),o={name:"daily/2026-08-06-uxtrend.md"};function s(i,r,g,p,h,d){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-08-06" tabindex="-1">设计趋势 - 2026-08-06 <a class="header-anchor" href="#设计趋势-2026-08-06" aria-label="Permalink to &quot;设计趋势 - 2026-08-06&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于人工智能与用户体验的深度融合。主要动态包括：1) 面向代理的用户体验设计，探索新型设计原则；2) AI设计交互范式，重塑数字产品；3) 为人工智能设计交互，提升体验；4) 人工智能辅助界面设计趋势，关注新趋势；5) Agentic UX，建立人机信任关系。最值得关注的是AI设计交互范式和Agentic UX，它们预示着人机协作的新方向。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探索数字设备中新型用户体验的设计原则</p><p><strong>能解决什么问题</strong>: 如何设计以人为本的智能代理系统以提升用户体验</p><p><strong>产品应用</strong>: 适用于数字产品开发，通过AI中心的设计原则指导产品迭代</p><p><strong>示例场景</strong>: 智能助手帮助用户在多任务中进行协作和学习</p><hr><h3 id="_2-ai设计交互范式" tabindex="-1">2. AI设计交互范式 <a class="header-anchor" href="#_2-ai设计交互范式" aria-label="Permalink to &quot;2. AI设计交互范式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://hanjing.medium.com/ai-interaction-paradigms-7caace4593ba" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI通过多种交互范式重塑数字产品。</p><p><strong>能解决什么问题</strong>: 解决AI产品中用户意图、自主性、可见性和控制的不同假设问题。</p><p><strong>产品应用</strong>: 适用于产品设计，指导创建可用、可信和直观的AI体验。</p><p><strong>示例场景</strong>: 设计一个基于用户意图的智能助手应用。</p><hr><h3 id="_3-为人工智能设计-设计ai特性的交互" tabindex="-1">3. 为人工智能设计：设计AI特性的交互 <a class="header-anchor" href="#_3-为人工智能设计-设计ai特性的交互" aria-label="Permalink to &quot;3. 为人工智能设计：设计AI特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: 探讨AI特性的交互设计，提升用户体验。</p><p><strong>能解决什么问题</strong>: 提高用户在使用AI工具时的效率和准确性。</p><p><strong>产品应用</strong>: 适用于需要快速、流畅交互的产品，如设计软件和写作工具。</p><p><strong>示例场景</strong>: 在Figma中自动完成地址输入，减少打字和错误。</p><hr><h3 id="_4-人工智能辅助界面设计趋势" tabindex="-1">4. 人工智能辅助界面设计趋势 <a class="header-anchor" href="#_4-人工智能辅助界面设计趋势" aria-label="Permalink to &quot;4. 人工智能辅助界面设计趋势&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@birdzhanhasan_26235/ai-ux-design-patterns-research-ff7b8056d07d" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探索AI辅助界面设计的新趋势，提升用户体验。</p><p><strong>能解决什么问题</strong>: 如何将AI辅助功能无缝融入用户工作流程。</p><p><strong>产品应用</strong>: 适用于需要AI辅助数据操作和分析的软件产品。</p><p><strong>示例场景</strong>: 智能电子表格软件中的数据分析和查询。</p><hr><h3 id="_5-agentic-ux-人机协作的新范式" tabindex="-1">5. Agentic UX：人机协作的新范式 <a class="header-anchor" href="#_5-agentic-ux-人机协作的新范式" aria-label="Permalink to &quot;5. Agentic UX：人机协作的新范式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Agentic UX设计关注于建立人机之间的信任关系。</p><p><strong>能解决什么问题</strong>: 如何使AI代理被接受、不被忽视或恐惧。</p><p><strong>产品应用</strong>: 适用于需要AI代理与用户协作的企业软件。</p><p><strong>示例场景</strong>: 在金融科技中，AI代理帮助用户做出投资决策。</p><hr><h3 id="_6-提升ai中介工作韧性的ux设计模式" tabindex="-1">6. 提升AI中介工作韧性的UX设计模式 <a class="header-anchor" href="#_6-提升ai中介工作韧性的ux设计模式" aria-label="Permalink to &quot;6. 提升AI中介工作韧性的UX设计模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@think_ui/designing-for-resilient-conversations-ux-design-patterns-for-ai-interfaces-727d6ce74f15" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 设计对话AI工具以提高工作韧性，确保在自动化降级时工作仍能继续。</p><p><strong>能解决什么问题</strong>: 解决AI中介工作中系统连续性、人的认知、知识信任和控制的失败问题。</p><p><strong>产品应用</strong>: 可应用于设计对话AI工具，通过减少脆弱性、保持用户主导权来提高工作韧性。</p><p><strong>示例场景</strong>: 在自动化客户服务中，通过对话AI工具提供备用方案以应对系统故障。</p><hr><h3 id="_7-ai-ux设计模式的更新与应用" tabindex="-1">7. AI UX设计模式的更新与应用 <a class="header-anchor" href="#_7-ai-ux设计模式的更新与应用" aria-label="Permalink to &quot;7. AI UX设计模式的更新与应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI UX设计模式的持续扩展与优化。</p><p><strong>能解决什么问题</strong>: 如何系统化地识别和定义AI UX设计模式。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过组合不同模式提升用户体验。</p><p><strong>示例场景</strong>: 结合多个设计模式创建有效的用户交互体验。</p><hr><h3 id="_8-ai工作流设计规则-超越对话式代理" tabindex="-1">8. AI工作流设计规则：超越对话式代理 <a class="header-anchor" href="#_8-ai工作流设计规则-超越对话式代理" aria-label="Permalink to &quot;8. AI工作流设计规则：超越对话式代理&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI系统失败常因工作流设计错误，非模型问题。</p><p><strong>能解决什么问题</strong>: 设计者常将AI误认为“某人”，而非“某物”，导致工作流设计不合理。</p><p><strong>产品应用</strong>: 适用于任何AI产品，应将AI功能直接嵌入工作流程中。</p><p><strong>示例场景</strong>: 在客户服务中，直接调用AI接口处理查询。</p><hr><h3 id="_9-人工智能时代下的用户体验2-0-agent-experience" tabindex="-1">9. 人工智能时代下的用户体验2.0（Agent Experience） <a class="header-anchor" href="#_9-人工智能时代下的用户体验2-0-agent-experience" aria-label="Permalink to &quot;9. 人工智能时代下的用户体验2.0（Agent Experience）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 用户体验设计不再局限于屏幕像素，而是扩展到人、代理和系统之间的逻辑、沟通和信任。</p><p><strong>能解决什么问题</strong>: 如何设计无缝衔接人类和机器认知的交互体验。</p><p><strong>产品应用</strong>: 可以应用到需要人工智能代理执行任务、共享反馈和做出决策的产品中。</p><p><strong>示例场景</strong>: AI代理代替人类预约医生，提供无缝的用户体验。</p><hr><h3 id="_10-figma中的ai工作流-图像、视频和创意生成" tabindex="-1">10. Figma中的AI工作流：图像、视频和创意生成 <a class="header-anchor" href="#_10-figma中的ai工作流-图像、视频和创意生成" aria-label="Permalink to &quot;10. Figma中的AI工作流：图像、视频和创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: AI工作流提供结构化的起点，助力创意项目从想法到输出。</p><p><strong>能解决什么问题</strong>: 解决AI工具生成内容时的一致性和创作步骤选择难题。</p><p><strong>产品应用</strong>: 适用于实际产品，通过自定义工作流模板实现快速创意生成。</p><p><strong>示例场景</strong>: 为营销活动生成产品视觉和故事板。</p><hr>',75)])])}const m=e(o,[["render",s]]);export{c as __pageData,m as default};
